(() => {
  const Z=window.Zucco,{state,platform:P,ui:U,ROUTES:R,escape:E,icon:I,avatar:A,btn:BT,badge:B,money:M}=Z;
  P.budgetPeriod='2026-10';
  const staffRows=()=>P.staff.filter(s=>U.match('staff',s.name,s.role,s.specialty,s.branch)).map(s=>`<tr><td><div class="row gap-12">${A(s.name,s.role==='Teacher'?'':'slate')}<div>${U.link(s.name,'ext-staff-details:'+s.id)}<p class="table-secondary">${E(s.specialty)}</p></div></div></td><td>${B(s.role,s.role==='Owner'?'accent':'')}</td><td>${E(s.branch)}</td><td class="mono caption">${s.phone}</td><td>${s.groups||'—'}</td><td>${U.status(s.status)}</td><td>${BT('Details','ext-staff-details:'+s.id,'chevron','small ghost')}</td></tr>`).join('');
  Z.listRenderers.staff=staffRows;
  Z.renderers[R.STAFF]=()=>Z.heading('Staff & teachers','The people behind every great learning experience.',BT('Roles & permissions','go:'+R.ROLES,'shield')+BT('Add staff','ext-new-staff','plus','primary'))+
    U.metrics([['Team members',P.staff.length,'Across all academy branches','users'],['Teachers',P.staff.filter(s=>s.role==='Teacher').length,'Active teaching team','book','success'],['Branch administrators',P.staff.filter(s=>['Owner','Administrator'].includes(s.role)).length,'Admissions and operations','building'],['Teaching groups',P.groups.length,'Supported by your team','group']])+
    U.toolbar('staff','Search staff, role, or subject…')+U.table([['Team member',26],['Role',14],['Branch',17],['Phone',18],['Groups',8],['Status',10],['',7]],staffRows(),'staff','<span>Permissions are assigned by role and branch.</span>');
  Z.payrollAmount=p=>p.base+p.bonus-p.deduction;
  const payrollRows=()=>P.payroll.filter(p=>U.match('payroll',p.teacher,p.scheme,p.status)).map(p=>`<tr><td><div class="row gap-12">${A(p.teacher)}<div><span class="table-primary">${p.teacher}</span><p class="table-secondary">${p.scheme}</p></div></div></td><td class="mono">${p.lessons}</td><td class="mono">${M(p.base)}</td><td class="mono text-success">${p.bonus?'+'+M(p.bonus):'—'}</td><td class="mono">${p.deduction?'−'+M(p.deduction):'—'}</td><td class="mono bold">${M(Z.payrollAmount(p))}</td><td>${U.status(p.status)}</td><td>${p.status==='Draft'?BT('Review','ext-payroll-review:'+p.id,'chevron','small'):p.status==='Approved'?BT('Pay salary','ext-payroll-pay:'+p.id,'wallet','small primary'):B('Paid in full','success')}</td></tr>`).join('');
  Z.listRenderers.payroll=payrollRows;
  Z.renderers[R.PAYROLL]=()=>Z.heading('Teacher payroll','Review the calculation, approve the amount, then pay in full.',`<label class="payroll-period"><span class="sr-only">Payroll period</span><input type="month" class="input" data-payroll-period value="${P.budgetPeriod}" max="2026-11"></label>`+BT('Calculate salary','ext-new-payroll','plus','primary'))+
    U.metrics([['Total payroll',M(P.payroll.reduce((a,p)=>a+Z.payrollAmount(p),0)),'UZS · '+P.budgetPeriod,'cash'],['Ready to pay',M(P.payroll.filter(p=>p.status==='Approved').reduce((a,p)=>a+Z.payrollAmount(p),0)),'Approved salaries · UZS','wallet','success'],['Awaiting approval',P.payroll.filter(p=>p.status==='Draft').length,'Review before any payout','clock'],['Paid',M(P.payroll.filter(p=>p.status==='Paid').reduce((a,p)=>a+Z.payrollAmount(p),0)),'Paid in full · UZS','checkCircle']])+
    U.toolbar('payroll','Search teacher, scheme, or status…')+U.table([['Teacher / scheme',25],['Lessons',8],['Calculated, UZS',13],['Bonus',10],['Deduction',10],['Final, UZS',13],['Status',10],['Action',11]],payrollRows(),'payroll','<span>Only completed, attendance-marked lessons are included.</span>')+
    `<p class="payroll-note">${I('shield')}Group-specific salary schemes take precedence. A salary is paid once, for the full approved amount.</p>`;
  P.historicalExpenses=[{id:'EXP-0084',name:'Yunusobod branch rent',course:'Rent & facilities',category:'Rent',amount:8500000,method:'Terminal',date:'1 Nov, 2026',kind:'expense'},{id:'EXP-0083',name:'Teaching materials',course:'Books & classroom materials',category:'Materials',amount:760000,method:'Cash',date:'1 Nov, 2026',kind:'expense'},{id:'EXP-0082',name:'November admissions campaign',course:'Marketing & advertising',category:'Marketing',amount:1200000,method:'Terminal',date:'1 Nov, 2026',kind:'expense'},{id:'EXP-0081',name:'Classroom maintenance',course:'Repairs & maintenance',category:'Facilities',amount:320000,method:'Cash',date:'1 Nov, 2026',kind:'expense'}];
  Z.allExpenses=()=>[...state.transactions.filter(t=>t.kind==='expense').map(t=>({...t,date:'2 Nov, 2026',category:t.name.toLowerCase().includes('internet')?'Utilities':t.name.toLowerCase().includes('salary')?'Payroll':'Materials'})),...P.historicalExpenses];
  const expenseRows=()=>Z.allExpenses().filter(t=>U.match('expenses',t.name,t.course,t.method,t.id)).map(t=>`<tr><td><div class="row gap-12"><span class="transaction-icon">${I('arrowUp')}</span><div><span class="table-primary">${E(t.name)}</span><p class="table-secondary mono">${t.id}</p></div></div></td><td>${B(t.category)}</td><td>${t.date}</td><td><span class="payment-method">${I(t.method==='Cash'?'cash':'card')}${t.method}</span></td><td class="text-end mono text-danger">−${M(t.amount)}</td><td>${U.status('Paid')}</td></tr>`).join('');
  Z.listRenderers.expenses=expenseRows;
  Z.renderers[R.EXPENSES]=()=>{const all=Z.allExpenses(),total=all.reduce((a,t)=>a+t.amount,0),categories=[...new Set(all.map(t=>t.category))].map(c=>({name:c,amount:all.filter(t=>t.category===c).reduce((a,t)=>a+t.amount,0)})).sort((a,b)=>b.amount-a.amount);return Z.heading('Expenses','Keep operating costs visible and your cash desk accountable.',BT('Record expense','record-expense','plus','primary'))+
    U.metrics([["Today's expenses",M(state.expenses),'UZS · 2 November','arrowUp'],['Month to date',M(total),'UZS · November 2026','wallet'],['Monthly budget','16,000,000','UZS · Operating expenses','calendar'],['Budget remaining',M(Math.max(0,16000000-total)),'UZS available this month','checkCircle','success']])+
    U.toolbar('expenses','Search expense, category, or reference…',B('November 2026'))+U.table([['Expense / reference',32],['Category',17],['Date',16],['Payment method',15],['Amount, UZS',14],['Status',10]],expenseRows(),'expenses','<span>Recorded expenses are included in financial reconciliation.</span>')+
    `<div class="expense-distribution">${U.panel('Monthly budget',`<div class="budget-summary"><span>Budget used</span><strong>${(total/16000000*100).toFixed(1)}%</strong></div><div style="height:18px"></div>${U.bars([['Operating budget',M(total)+' / 16M',Math.min(total/16000000*100,100)]])}`)}${U.panel('Spending by category',U.bars(categories.slice(0,4).map(c=>[c.name,M(c.amount)+' UZS',Math.max(4,c.amount/total*100)])))}</div>`;};
})();
